preConditionHook:
// Entry & Exit Confessions #2 (Everyone Loves Friday), verbatim: Friday's
// close is the highest (long) / lowest (short) close of bbars bars.
// EL DayOfWeek(Date): 0 = Sunday .. 6 = Saturday, of the bar's wall-clock
// close date (EL_Date_Probe.txt, 169/169 incl. evening bars). day_of_week()
// in time.h uses the same numbering.
dow = day_of_week(day_of(ctx.Time(0)));
highestClose = close[0];
lowestClose = close[0];
// Mirrors EasyLanguage's Extremes(), which Highest()/Lowest() call: seeded
// at bar 0, scanning bars 1..Length-1, strict comparison (so a tie keeps the
// earliest bar). Extremes is EL SOURCE, so its comparison carries the EL
// tolerance -- el_gt/el_lt, as in Breakout (the reference).
for (int i = 1; i < (int)bbars; ++i) {
    if (el_gt(close[i], highestClose)) highestClose = close[i];
    if (el_lt(close[i], lowestClose)) lowestClose = close[i];
}
